"use client";

import { type ComponentPropsWithoutRef, forwardRef } from "react";
import { usePointerAdjust } from "./number-field-scrub";
import { handleTypingKeys, mergeRefs, useNumberField } from "./number-field-state";
import { cn } from "@/lib/utils";

/** The visible label. Clicking it focuses the input. */
export const NumberFieldLabel = forwardRef<HTMLLabelElement, ComponentPropsWithoutRef<"label">>(function NumberFieldLabel(
  { className, children, ...props },
  ref,
) {
  const { label, labelId, inputId } = useNumberField();
  return (
    <label ref={ref} id={labelId} htmlFor={inputId} data-slot="label" className={cn("text-xs text-muted-foreground select-none", className)} {...props}>
      {children ?? label}
    </label>
  );
});

/**
 * The field's box: holds the input, unit and stepper, and shows focus and invalid states
 * for all of them. Pressing anywhere in it focuses the input.
 */
export const NumberFieldGroup = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function NumberFieldGroup(
  { className, onMouseDown, ...props },
  ref,
) {
  const { inputRef, stepperLayout } = useNumberField();
  return (
    <div
      ref={ref}
      data-slot="group"
      data-layout={stepperLayout}
      className={cn(
        "group/numeric flex h-[var(--uicoolkit-field-height,2.5rem)] min-w-0 flex-1 items-stretch overflow-hidden rounded-md border border-[color:var(--uicoolkit-field-border,var(--input))] bg-[var(--uicoolkit-field-bg,transparent)] shadow-[var(--uicoolkit-field-shadow,0_1px_2px_0_rgb(0_0_0/0.05))] focus-within:border-ring has-[input:disabled]:opacity-50 has-[input[aria-invalid=true]]:border-destructive has-[input[aria-invalid=true]]:ring-destructive/20",
        className,
      )}
      onMouseDown={(event) => {
        onMouseDown?.(event);
        const target = event.target as HTMLElement;
        if (event.defaultPrevented || target.closest("input, button")) return;
        event.preventDefault();
        inputRef.current?.focus();
      }}
      {...props}
    />
  );
});

type InputProps = Omit<ComponentPropsWithoutRef<"input">, "value" | "defaultValue" | "type"> & {
  /**
   * Drag left or right over the number to adjust it, as over the label (the default). A click without
   * moving still starts typing; while typing, the pointer selects text as usual. Set false to turn it off.
   */
  scrub?: boolean;
};

/** A text input that behaves as a spin button: type and press Enter, or step with the arrow keys. Place it in NumberFieldGroup. */
export const NumberFieldInput = forwardRef<HTMLInputElement, InputProps>(function NumberFieldInput(
  { className, onChange, onKeyDown, onFocus, onBlur, onPointerDown, onPointerMove, onPointerUp, onPointerCancel, onMouseDown, scrub = true, ...props },
  ref,
) {
  const field = useNumberField();
  const adjust = usePointerAdjust({
    valueAt: (start, dx, _width, event) => start + Math.round(dx / field.sensitivity) * (event.shiftKey ? field.largeStep : field.step),
    onTap: () => field.inputRef.current?.focus(),
  });
  const unitShown = !!field.unit && !(field.display === null && field.draft === null);
  // Only an idle number is a drag handle; once focused, the input edits text.
  const idle = (target: EventTarget) => scrub && !field.disabled && !field.readOnly && document.activeElement !== target;
  return (
    <input
      ref={mergeRefs(ref, field.inputRef)}
      id={field.inputId}
      type="text"
      inputMode="decimal"
      autoComplete="off"
      spellCheck={false}
      role="spinbutton"
      aria-label={field.label}
      aria-valuenow={field.display ?? undefined}
      aria-valuemin={field.min}
      aria-valuemax={field.max}
      aria-valuetext={field.valueText}
      aria-invalid={field.error ? true : undefined}
      aria-describedby={field.error ? field.errorId : undefined}
      disabled={field.disabled}
      readOnly={field.readOnly}
      placeholder={field.placeholder}
      className={cn(
        // Numbers line up on the right, next to their unit; the group draws the box.
        "w-full min-w-0 flex-1 bg-transparent pl-2 text-right text-sm tabular-nums outline-none placeholder:text-muted-foreground",
        // A shown unit supplies the gap before the stepper; without one ("Mixed", or no unit) the input keeps the same gap.
        unitShown ? "pr-1" : "pr-2",
        scrub && !field.disabled && !field.readOnly && field.adjustFrom !== null && "touch-pan-y not-focus:cursor-ew-resize",
        className,
      )}
      {...props}
      value={field.draft ?? field.text}
      onMouseDown={(event) => {
        onMouseDown?.(event);
        // Keep an idle number from taking focus or selecting text on press; a tap focuses it on release.
        if (!event.defaultPrevented && event.button === 0 && idle(event.currentTarget)) event.preventDefault();
      }}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        if (event.defaultPrevented || !idle(event.currentTarget)) return;
        if (event.pointerType === "mouse") event.preventDefault();
        adjust.onPointerDown(event);
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        adjust.onPointerMove(event);
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event);
        adjust.onPointerUp(event);
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event);
        adjust.onPointerCancel(event);
      }}
      onFocus={(event) => {
        onFocus?.(event);
        const input = event.currentTarget;
        // An empty value can still stand for something to edit, such as a merged field's list.
        if (field.draft === null && field.display === null && field.editText && !field.readOnly) {
          field.setDraft(field.editText);
          // Focus updates render before microtasks run, so this selects the prefilled text before any typing.
          queueMicrotask(() => input.select());
        } else input.select();
      }}
      onChange={(event) => {
        onChange?.(event);
        if (!event.defaultPrevented) field.setDraft(event.target.value);
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (!event.defaultPrevented) handleTypingKeys(event, field);
      }}
      onBlur={(event) => {
        onBlur?.(event);
        // An invalid draft stays in the field with its message until it is fixed or reverted.
        field.submitDraft();
      }}
    />
  );
});

/** The unit after the value. Hidden from assistive technology, which reads it in the value text. */
export const NumberFieldUnit = forwardRef<HTMLSpanElement, ComponentPropsWithoutRef<"span">>(function NumberFieldUnit(
  { className, children, ...props },
  ref,
) {
  const { unit, display, draft } = useNumberField();
  // A placeholder such as "Mixed" reads on its own.
  if ((!unit && !children) || (display === null && draft === null)) return null;
  return (
    <span ref={ref} aria-hidden className={cn("flex items-center pr-2 text-xs text-muted-foreground select-none", className)} {...props}>
      {children ?? unit}
    </span>
  );
});

/** The validation message for a rejected typed value. */
export const NumberFieldError = forwardRef<HTMLParagraphElement, ComponentPropsWithoutRef<"p">>(function NumberFieldError(
  { className, children, ...props },
  ref,
) {
  const { error, errorId } = useNumberField();
  if (!error) return null;
  return (
    <p ref={ref} id={errorId} data-slot="error" role="alert" className={cn("basis-full text-xs text-destructive", className)} {...props}>
      {children ?? error}
    </p>
  );
});

"use client";

import { Select } from "@base-ui/react/select";
import { useRef, useState, useSyncExternalStore } from "react";
import { useNumberField } from "./number-field-state";
import { cn } from "@/lib/utils";

const phoneQuery = "(max-width: 639px)";
const subscribe = (notify: () => void) => {
  if (typeof window.matchMedia !== "function") return () => {};
  const media = window.matchMedia(phoneQuery);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
/** Phones get a bottom sheet; the server renders the desktop popup, then adapts. */
const usePhone = () =>
  useSyncExternalStore(subscribe, () => typeof window.matchMedia === "function" && window.matchMedia(phoneQuery).matches, () => false);

/** The menu's value for a plain number. */
const fixed = "__fixed";

type KeywordMenuProps = {
  className?: string;
  /** Class for the popup (or the bottom sheet on phones). */
  popupClassName?: string;
  /** Class for each option. Highlighted options have data-highlighted; the chosen one data-selected. */
  itemClassName?: string;
  /** For narrow fields, such as a design tool's grid: Fixed shows only the arrow, leaving room for the number. Keywords still show. */
  compact?: boolean;
};

/**
 * Picks Fixed or one of the field's keywords, at the end of NumberFieldGroup; the menu opens at the field's width. It shows the current
 * mode, except for a keyword the input already spells out (Auto). Fixed keeps the shown number.
 */
export function NumberFieldKeywordMenu({ className, popupClassName, itemClassName, compact = false }: KeywordMenuProps) {
  const field = useNumberField();
  const phone = usePhone();
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement | null>(null);
  const blocked = field.readOnly || field.disabled;
  const options = [{ value: fixed, label: field.messages.fixed }, ...field.keywords.map((keyword) => ({ value: keyword.value, label: keyword.label }))];
  const current = field.keyword ? field.keyword.value : field.value !== null ? fixed : null;
  // A keyword without a number already reads in the input, so the trigger shows only its arrow.
  const shown =
    (field.keyword && field.display === null && field.draft === null) || (compact && current === fixed) ? null : (options.find((option) => option.value === current)?.label ?? null);

  return (
    <Select.Root
      items={options}
      value={current}
      onValueChange={(next) => {
        if (next === null || next === current) return;
        field.setKeyword(next === fixed ? null : (next as string));
      }}
      disabled={field.disabled}
      readOnly={field.readOnly}
      open={open && !blocked}
      onOpenChange={(next) => setOpen(next && !blocked)}
    >
      <Select.Trigger
        ref={trigger}
        aria-label={field.messages.mode(field.label)}
        data-slot="keyword"
        className={cn(
          "flex shrink-0 items-center gap-1.5 self-stretch text-sm",
          compact ? "pr-2 pl-0.5" : "pr-2.5 pl-1.5",
          "text-muted-foreground outline-none select-none hover:text-foreground focus-visible:text-foreground data-[popup-open]:text-foreground data-[readonly]:pointer-events-none",
          className,
        )}
      >
        {shown && <span>{shown}</span>}
        {!blocked && (
          <svg aria-hidden viewBox="0 0 10 6" className="h-1.5 w-2.5" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
            <path d="M1.5 1.25 5 4.75l3.5-3.5" />
          </svg>
        )}
      </Select.Trigger>
      <Select.Portal container={field.container ?? undefined}>
        {phone && <Select.Backdrop className="fixed inset-0 z-50 bg-black/40" />}
        <Select.Positioner
          // The menu opens under the whole field, at its width, not under the small trigger. A host whose
          // visible box is larger, such as a row with its label inside, marks that box data-menu-anchor.
          anchor={() => trigger.current?.closest<HTMLElement>("[data-menu-anchor]") ?? trigger.current?.closest<HTMLElement>('[data-slot="group"]') ?? trigger.current}
          alignItemWithTrigger={false}
          side="bottom"
          align="start"
          sideOffset={6}
          positionMethod="fixed"
          className="z-50 outline-none"
          style={phone ? { position: "fixed", top: "auto", bottom: 0, left: 0, right: 0, width: "100%", transform: "none" } : undefined}
        >
          <Select.Popup
            className={cn(
              // At least the field's width, wider only if an option needs it.
              "max-h-[var(--available-height)] w-max min-w-[var(--anchor-width)] overflow-y-auto rounded-md border border-border bg-popover p-1 text-popover-foreground shadow-md outline-none",
              phone && "max-h-[80dvh] w-full rounded-t-2xl rounded-b-none p-4 pb-[max(1rem,env(safe-area-inset-bottom))]",
              field.animated &&
                (phone
                  ? "transition-[transform,opacity] duration-200 ease-out data-[ending-style]:translate-y-full data-[starting-style]:translate-y-full motion-reduce:transition-none"
                  : "origin-[var(--transform-origin)] transition-[transform,opacity] duration-150 ease-out data-[ending-style]:scale-95 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[starting-style]:opacity-0 motion-reduce:transition-none"),
              popupClassName,
            )}
          >
            <Select.List>
              {options.map((option) => (
                <Select.Item
                  key={option.value}
                  value={option.value}
                  className={cn(
                    "flex min-h-8 cursor-pointer items-center justify-between gap-3 rounded-sm px-2 text-sm outline-none select-none data-[highlighted]:bg-accent data-[highlighted]:text-accent-foreground",
                    phone && "min-h-11",
                    itemClassName,
                  )}
                >
                  <Select.ItemText>{option.label}</Select.ItemText>
                  <Select.ItemIndicator data-slot="check">
                    <svg aria-hidden viewBox="0 0 16 16" className="size-3.5" fill="none" stroke="currentColor" strokeWidth={1.75} strokeLinecap="round" strokeLinejoin="round">
                      <path d="m3.5 8.5 3 3 6-7" />
                    </svg>
                  </Select.ItemIndicator>
                </Select.Item>
              ))}
            </Select.List>
          </Select.Popup>
        </Select.Positioner>
      </Select.Portal>
    </Select.Root>
  );
}

"use client";

import { type ReactElement, type RefAttributes, forwardRef, useId, useRef, useState } from "react";
import { type NumberFieldContextValue, type NumberFieldProps, NumberFieldContext, decimalsOf, defaultMessages } from "./number-field-state";
import { cn } from "@/lib/utils";

const NumberFieldRoot = forwardRef<HTMLDivElement, NumberFieldProps<string>>(function NumberField(
  {
    value,
    onValueCommit,
    onValueChange,
    label,
    min,
    max,
    step = 1,
    largeStep = step * 10,
    precision = decimalsOf(step),
    unit,
    format,
    parse,
    validate,
    placeholder,
    disabled = false,
    readOnly = false,
    sensitivity = 4,
    motion = true,
    stepperLayout = "auto",
    keywords = [],
    keywordFallback,
    container,
    submitText,
    editText,
    messages: messagesProp,
    className,
    ...props
  },
  ref,
) {
  const [preview, setPreview] = useState<number | null>(null);
  const [draft, setDraftValue] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [dragging, setDragging] = useState(false);
  // Pointer events can arrive faster than renders, so the drag reads its latest value here.
  const live = useRef<number | null>(null);
  // Mirrors the draft so a blur that follows Enter, Escape or a step cannot commit it twice.
  const draftRef = useRef<string | null>(null);
  const inputRef = useRef<HTMLInputElement | null>(null);
  const sliderRef = useRef<HTMLDivElement | null>(null);
  const id = useId();
  const messages = { ...defaultMessages, ...messagesProp };
  const locked = disabled || readOnly;

  const normalize = (next: number) => Math.min(max ?? Infinity, Math.max(min ?? -Infinity, Number(next.toFixed(precision))));
  const formatValue = (next: number) => (format ? format(next) : next.toFixed(precision));
  const parseText = (text: string) => {
    if (parse) return parse(text);
    let cleaned = text.trim().replace(/−/g, "-");
    if (unit && cleaned.endsWith(unit)) cleaned = cleaned.slice(0, -unit.length).trim();
    return cleaned === "" ? NaN : Number(cleaned);
  };

  const setDraftState = (next: string | null) => {
    draftRef.current = next;
    setDraftValue(next);
  };

  // A keyword stands in for the number; one with a resolved size still shows that size.
  const number = typeof value === "number" ? value : null;
  const keyword = typeof value === "string" ? (keywords.find((item) => item.value === value) ?? null) : null;
  const display = preview ?? number ?? keyword?.resolved ?? null;
  const text = display !== null ? formatValue(display) : keyword ? keyword.label : "";
  const adjustFrom = display ?? (keyword ? (keywordFallback ?? min ?? 0) : null);
  const keywordFor = (typed: string) => {
    const name = typed.trim().toLowerCase();
    return keywords.find((item) => item.label.toLowerCase() === name || item.value.toLowerCase() === name) ?? null;
  };

  const commit = (next: number) => {
    const normalized = normalize(next);
    live.current = null;
    setPreview(null);
    if (normalized === value) return;
    onValueChange?.(normalized);
    onValueCommit(normalized);
  };

  const commitKeyword = (next: string) => {
    live.current = null;
    setPreview(null);
    if (next === value) return;
    onValueChange?.(next);
    onValueCommit(next);
  };

  const cancelDraft = () => {
    setDraftState(null);
    setError(null);
  };

  const submitDraft = () => {
    const draft = draftRef.current;
    if (draft === null) return true;
    // Clearing the text reverts rather than committing an empty value.
    if (draft.trim() === "") {
      cancelDraft();
      return true;
    }
    // The host reads its own forms first, such as a list of values.
    const handled = submitText?.(draft);
    if (handled === true) {
      cancelDraft();
      return true;
    }
    if (typeof handled === "string") {
      setError(handled);
      return false;
    }
    // A keyword's name selects it, such as "auto".
    const typedKeyword = keywordFor(draft);
    if (typedKeyword) {
      cancelDraft();
      commitKeyword(typedKeyword.value);
      return true;
    }
    const parsed = parseText(draft);
    if (!Number.isFinite(parsed)) {
      setError(messages.invalid);
      return false;
    }
    // Typed values outside the limits are rejected rather than silently clamped.
    const rounded = Number(parsed.toFixed(precision));
    // Symbol units such as % and ° attach to the number; word units such as px take a space.
    const withUnit = (limit: number) => (!unit ? formatValue(limit) : /^[%°′″]$/.test(unit) ? `${formatValue(limit)}${unit}` : `${formatValue(limit)} ${unit}`);
    if (min !== undefined && rounded < min) {
      setError(messages.tooLow.replace("{min}", withUnit(min)));
      return false;
    }
    if (max !== undefined && rounded > max) {
      setError(messages.tooHigh.replace("{max}", withUnit(max)));
      return false;
    }
    const normalized = normalize(rounded);
    const message = validate?.(normalized);
    if (message) {
      setError(message);
      return false;
    }
    cancelDraft();
    commit(normalized);
    return true;
  };

  const stepBy = (steps: number, large = false) => {
    if (locked) return;
    const typed = draftRef.current === null ? NaN : parseText(draftRef.current);
    // Stepping a keyword turns it into a number, from its resolved size or the fallback.
    const base = Number.isFinite(typed) ? typed : adjustFrom;
    // A mixed value has no common base to step from; typing sets one.
    if (base === null) return;
    cancelDraft();
    commit(base + steps * (large ? largeStep : step));
  };

  const cancelDrag = () => {
    live.current = null;
    setPreview(null);
    setDragging(false);
    if (value !== null) onValueChange?.(value);
  };

  const context: NumberFieldContextValue = {
    label,
    value: number,
    keyword,
    keywords,
    adjustFrom,
    setKeyword: (next) => {
      if (locked) return;
      cancelDraft();
      if (next !== null) commitKeyword(next);
      else if (adjustFrom !== null) commit(adjustFrom);
    },
    container,
    editText,
    display,
    text,
    valueText:
      display === null
        ? (keyword?.label ?? placeholder)
        : `${unit ? `${text} ${unit}` : text}${keyword ? `, ${keyword.label}` : ""}`,
    unit,
    min,
    max,
    step,
    largeStep,
    sensitivity,
    placeholder,
    disabled,
    readOnly,
    animated: motion,
    stepperLayout,
    dragging,
    draft,
    error,
    messages,
    inputId: `${id}-input`,
    labelId: `${id}-label`,
    errorId: `${id}-error`,
    inputRef,
    sliderRef,
    setDraft: (next) => {
      setDraftState(next);
      if (error) setError(null);
    },
    beginTyping: () => !locked && setDraftState(text),
    submitDraft,
    cancelDraft,
    stepBy,
    commit: (next) => !locked && commit(next),
    beginDrag: () => {
      if (locked || adjustFrom === null) return null;
      cancelDraft();
      setDragging(true);
      return adjustFrom;
    },
    dragTo: (next) => {
      const normalized = normalize(next);
      if (normalized === live.current) return;
      live.current = normalized;
      setPreview(normalized);
      onValueChange?.(normalized);
    },
    endDrag: () => {
      setDragging(false);
      if (live.current === null) return;
      commit(live.current);
    },
    cancelDrag,
  };

  return (
    <NumberFieldContext.Provider value={context}>
      <div
        ref={ref}
        data-dragging={dragging || undefined}
        data-typing={draft !== null || undefined}
        data-invalid={error ? true : undefined}
        data-empty={display === null || undefined}
        data-disabled={disabled || undefined}
        data-readonly={readOnly || undefined}
        className={cn("flex flex-wrap items-center gap-x-2 gap-y-1", className)}
        {...props}
      />
    </NumberFieldContext.Provider>
  );
});

/**
 * A number your app owns, typed, stepped or dragged. With `keywords`, it can also hold a named value
 * such as Auto or Hug; the value's type then widens to include them.
 */
export const NumberField = NumberFieldRoot as <K extends string = never>(props: NumberFieldProps<K> & RefAttributes<HTMLDivElement>) => ReactElement | null;

"use client";

import { type ComponentPropsWithoutRef, type PointerEvent, forwardRef, useEffect, useRef } from "react";
import { useNumberField } from "./number-field-state";
import { cn } from "@/lib/utils";

/** Pointer travel before a press becomes a drag, so a click or tap still works. */
const threshold = 3;

type Gesture = { pointerId: number; x: number; width: number; start: number | null; moved: boolean };

/**
 * Turns a horizontal drag on an element into live values and one commit on release.
 * `valueAt` maps the start value and pointer travel to the next value. A press without
 * movement calls `onTap`. Escape or a cancelled pointer restores the committed value.
 */
export function usePointerAdjust({ valueAt, onTap }: { valueAt: (start: number, dx: number, width: number, event: PointerEvent<HTMLElement>) => number; onTap?: () => void }) {
  const field = useNumberField();
  const gesture = useRef<Gesture | null>(null);
  const cancelDrag = field.cancelDrag;

  useEffect(() => {
    if (!field.dragging) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape" || !gesture.current) return;
      event.preventDefault();
      event.stopPropagation();
      gesture.current = null;
      cancelDrag();
    };
    window.addEventListener("keydown", onKeyDown, true);
    return () => window.removeEventListener("keydown", onKeyDown, true);
  }, [field.dragging, cancelDrag]);

  const finish = (event: PointerEvent<HTMLElement>, cancelled: boolean) => {
    const current = gesture.current;
    if (!current || current.pointerId !== event.pointerId) return;
    gesture.current = null;
    if (event.currentTarget.hasPointerCapture?.(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    if (current.moved) {
      if (cancelled) field.cancelDrag();
      else field.endDrag();
    } else if (!cancelled) onTap?.();
  };

  return {
    onPointerDown: (event: PointerEvent<HTMLElement>) => {
      if (event.button !== 0 || field.disabled || field.readOnly || field.draft !== null) return;
      event.currentTarget.setPointerCapture?.(event.pointerId);
      const width = event.currentTarget.getBoundingClientRect().width;
      gesture.current = { pointerId: event.pointerId, x: event.clientX, width, start: field.adjustFrom, moved: false };
    },
    onPointerMove: (event: PointerEvent<HTMLElement>) => {
      const current = gesture.current;
      if (!current || current.pointerId !== event.pointerId || current.start === null) return;
      const dx = event.clientX - current.x;
      if (!current.moved) {
        if (Math.abs(dx) < threshold) return;
        current.moved = true;
        field.beginDrag();
      }
      field.dragTo(valueAt(current.start, dx, current.width, event));
    },
    onPointerUp: (event: PointerEvent<HTMLElement>) => finish(event, false),
    // Fired when the browser takes over, such as a vertical scroll on touch.
    onPointerCancel: (event: PointerEvent<HTMLElement>) => finish(event, true),
  };
}

/**
 * Drag left or right over this area to adjust the value, usually around the label.
 * Each `sensitivity` pixels is one step; hold Shift for large steps. A click focuses the input.
 */
export const NumberFieldScrubArea = forwardRef<HTMLSpanElement, ComponentPropsWithoutRef<"span">>(function NumberFieldScrubArea(
  { className, onPointerDown, onPointerMove, onPointerUp, onPointerCancel, ...props },
  ref,
) {
  const field = useNumberField();
  const adjust = usePointerAdjust({
