    valueAt: (start, dx, width) => start + Math.round(((dx / width) * range) / field.step) * field.step,
    onTap: field.beginTyping,
  });

  const showSteps = () => {
    clearTimeout(linger.current);
    setKeyStepping(true);
    linger.current = setTimeout(() => setKeyStepping(false), keyStepLinger);
